}

.step-title {
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.step-desc {
  color: var(--color-text-muted);
  font-size: 0.8125rem;
}

/* Support Cards */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}

@media (max-width: 700px) {
  .support-grid {
    grid-template-columns: 1fr;
